## Method and reasoning
For at most k distinct values, shrink the window until valid. Every suffix of that window ending at the same right position is valid, so add its length. Subtract atMost(k−1) from atMost(k). Compress values before using a flat frequency table.

## Walk through the sample
For [1,2,1,2,3], ten windows ending in the first four positions use at most two distinct values. Two more end at 3. Five singleton windows use at most one, leaving 12 − 5 = 7 with exactly two.

## Complexity
Total time O(n log n), including compression, and space O(n).

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

long long atMost(const vector<int> &a, int k) {
    vector<int> freq(a.size());
    int l = 0, distinct = 0;
    long long count = 0;
    for (int r = 0; r < int(a.size()); ++r) {
        distinct += ++freq[a[r]] == 1;
        while (distinct > k)
            distinct -= --freq[a[l++]] == 0;
        count += r - l + 1;
    }
    return count;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (auto &x : a)
        cin >> x;
    auto keys = a;
    sort(keys.begin(), keys.end());
    keys.erase(unique(keys.begin(), keys.end()), keys.end());
    for (auto &x : a)
        x = lower_bound(keys.begin(), keys.end(), x) - keys.begin();
    cout << atMost(a, k) - atMost(a, k - 1) << '\n';
}
